(384,78,'_elementor_data','[{\"id\":\"9987985\",\"elType\":\"e-flexbox\",\"settings\":{\"classes\":{\"$$type\":\"classes\",\"value\":[\"e-8931e4a\"]}},\"elements\":[{\"id\":\"db8d183\",\"elType\":\"widget\",\"settings\":{\"classes\":{\"$$type\":\"classes\",\"value\":[\"e-db8d183-e8a7bb1\"]},\"title\":{\"$$type\":\"html-v3\",\"value\":{\"content\":{\"$$type\":\"string\",\"value\":\"Terms &amp; Conditions\"},\"children\":[]}},\"link\":{\"$$type\":\"link\",\"value\":{\"isTargetBlank\":null}}},\"elements\":[],\"widgetType\":\"e-heading\",\"styles\":{\"e-db8d183-e8a7bb1\":{\"id\":\"e-db8d183-e8a7bb1\",\"label\":\"local\",\"type\":\"class\",\"variants\":[{\"meta\":{\"breakpoint\":\"desktop\",\"state\":null},\"props\":{\"align-self\":{\"$$type\":\"string\",\"value\":\"center\"}},\"custom_css\":null}]}},\"interactions\":[],\"editor_settings\":[],\"version\":\"0.0\"},{\"id\":\"610037f\",\"elType\":\"widget\",\"settings\":{\"html\":\"<!DOCTYPE html>\\n<html lang=\\\"en\\\">\\n<head>\\n    <meta charset=\\\"UTF-8\\\" \\/>\\n    <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\" \\/>\\n    <title>Terms of Use \\u2014 Sampreshan | Vasudhaiva Kutumbakam<\\/title>\\n    <meta name=\\\"description\\\" content=\\\"Read the Terms of Use for Sampreshan \\u2014 a digital initiative inspired by ShivBodh Trust for preserving and promoting Sanatana Dharma through respectful community participation.\\\" \\/>\\n    <meta name=\\\"robots\\\" content=\\\"index, follow\\\" \\/>\\n    <link rel=\\\"canonical\\\" href=\\\"https:\\/\\/sampreshan.org\\/terms-of-use.html\\\" \\/>\\n\\n    <!-- Open Graph -->\\n    <meta property=\\\"og:title\\\" content=\\\"Terms of Use \\u2014 Sampreshan\\\" \\/>\\n    <meta property=\\\"og:description\\\" content=\\\"Read the Terms of Use for Sampreshan \\u2014 a digital initiative inspired by ShivBodh Trust for preserving and promoting Sanatana Dharma.\\\" \\/>\\n    <meta property=\\\"og:type\\\" content=\\\"website\\\" \\/>\\n   