               Have a question about these Terms of Use or need clarification? Reach out to us \\u2014\\n                        we are here to help.\\n                    <\\/p>\\n                    <a href=\\\"mailto:sampreshan.tech@gmail.com\\\" class=\\\"email-link\\\" aria-label=\\\"Send an email to Sampreshan\\\">\\n                        <span aria-hidden=\\\"true\\\">\\u2709\\ufe0f<\\/span> sampreshan.tech@gmail.com\\n                    <\\/a>\\n\\n                    <div class=\\\"contact-placeholders\\\">\\n                        <div class=\\\"placeholder-box\\\">\\n                            <span class=\\\"placeholder-label\\\">\\u23f3 Placeholder<\\/span>\\n                            <div class=\\\"placeholder-content\\\">\\n                                <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83c\\udfe2<\\/span>\\n                                Registered Office Address\\n                            <\\/div>\\n                            <div class=\\\"placeholder-note\\\">Registered office address<\\/div>\\n                        <\\/div>\\n                        <div class=\\\"placeholder-box\\\">\\n                            <span class=\\\"placeholder-label\\\">\\u23f3 Placeholder<\\/span>\\n                            <div class=\\\"placeholder-content\\\">\\n                                <span class=\\\"icon\\\" aria-hidden=\\\"true\\\">\\ud83d\\udc64<\\/span>\\n                                Legal Contact Person\\n                            <\\/div>\\n                            <div class=\\\"placeholder-note\\\">Legal &amp; compliance contact<\\/div>\\n                        <\\/div>\\n                    <\\/div>\\n                <\\/div>\\n            <\\/div>\\n        <\\/section>\\n\\n    <\\/main>\\n\\n    <!-- ===== Footer ===== -->\\n    <footer class=\\\"site-footer\\\" role=\\\"contentinfo\\\" aria-label=\\\"Site footer\\\">\\n        <div class=\\\"container footer-inner\\\">\\n            <div class=\\\"footer-brand\\\">\\n                <div class=\\\"footer-logo\\\">Sampreshan<span>.<\\/span><\\/div>\\n                <div class=\\\"footer-tagline\\\">Vasudhaiva Kutumbakam<\\/div>\\n            <\\/div>\\n            <ul class=\\\"footer-links\\\">\\n                <li><a href=\\\"\\/about.html\\\">About<\\/a><\\/li>\\n                <li><a href=\\\"\\/privacy-policy.html\\\">Privacy Policy<\\/a><\\/li>\\n                <li><a href=\\\"\\/terms-of-use.html\\\" aria-current=\\\"page\\\">Terms of Use<\\/a><\\/li>\\n                <li><a href=\\\"mailto:sampreshan.tech@gmail.com\\\">Contact<\\/a><\\/li>\\n            <\\/ul>\\n            <div class=\\\"footer-copy\\\">\\n                &copy; <span class=\\\"year\\\" id=\\\"year\\\"><\\/span> Sampreshan. All rights reserved.\\n            <\\/div>\\n        <\\/div>\\n    <\\/footer>\\n\\n    <!-- ===== JavaScript ===== -->\\n    <script>\\n        (function() {\\n            \'use strict\';\\n\\n            \\/\\/ ---- Auto-update copyright year ----\\n            document.getElementById(\'year\').textContent = new Date().getFullYear();\\n\\n            \\/\\/ ---- Mobile nav toggle ----\\n            const toggle = document.getElementById(\'navToggle\');\\n            const navLinks = document.getElementById(\'navLinks\');\\n\\n            if (toggle && navLinks) {\\n                toggle.addEventListener(\'click\', function() {\\n                    const expanded = this.getAttribute(\'aria-expanded\') === \'true\' ? false : true;\\n                    this.setAttribute(\'aria-expanded\', expanded);\\n                    navLinks.classList.toggle(\'open\');\\n                });\\n\\n                navLinks.querySelectorAll(\'a\').forEach(function(link) {\\n                    link.addEventListener(\'click\', function() {\\n                        toggle.setAttribute(\'aria-expanded\', \'false\');\\n                        navLinks.classList.remove(\'open\');\\n                    });\\n                });\\n            }\\n\\n            \\/\\/ ---- Intersection Observer for scroll animations ----\\n            const animateElements = document.querySelectorAll(\'.animate-on-view\');\\n\\n            if (\'IntersectionObserver\' in window) {\\n                const observer = new IntersectionObserver(function(entries) {\\n                    entries.forEach(function(entry) {\\n                        if (entry.isIntersecting) {\\n                            entry.target.classList.add(\'visible\');\\n                            observer.unobserve(entry.target);\\n                        }\\n                    });\\n                }, {\\n                    threshold: 0.12,\\n                    rootMargin: \'0px 0px -30px 0px\'\\n                });\\n\\n                animateElements.forEach(function(el) {\\n                    observer.observe(el);\\n                });\\n            } else {\\n                animateElements.forEach(function(el) {\\n                    el.classList.add(\'visible\');\\n                });\\n            }\\n\\n            \\/\\/ ---- Smooth anchor scroll ----\\n            document.querySelectorAll(\'a[href^=\\\"#\\\"]\').forEach(function(anchor) {\\n                anchor.addEventListener(\'click\', function(e) {\\n                    const targetId = this.getAttribute(\'href\');\\n                    if (targetId === \'#\') return;\\n                    const target = document.querySelector(targetId);\\n                    if (target) {\\n                        e.preventDefault();\\n                        const headerOffset = 80;\\n                        const elementPosition = target.getBoundingClientRect().top;\\n                        const offsetPosition = elementPosition + window.pageYOffset - headerOffset;\\n                        window.scrollTo({\\n                            top: offsetPosition,\\n                            behavior: \'smooth\'\\n                        });\\n                        history.pushState(null, null, targetId);\\n                    }\\n                });\\n            });\\n\\n        })();\\n    <\\/script>\\n\\n<\\/body>\\n<\\/html>\",\"custom_css\":\"\\/* ============================================================\\n   TERMS OF USE \\u2014 Sampreshan\\n   Complete CSS Stylesheet\\n   Mobile-First | Responsive | Modern Spiritual Design\\n   ============================================================ *\\/\\n\\n\\/* ===== CSS Variables ===== *\\/\\n:root {\\n    --saffron: #FF9933;\\n    --saffron-dark: #e0851a;\\n    --saffron-light: #ffe4b3;\\n    --deep-blue: #1E3A8A;\\n    --deep-blue-dark: #152b66;\\n    --deep-blue-light: #2a4bb5;\\n    --white: #FFFFFF;\\n    --off-white: #f8f6f0;\\n    --light-bg: #f5f2eb;\\n    --gray-light: #e8e4da;\\n    --gray-mid: #8a867a;\\n    --text-dark: #1a1a1a;\\n    --text-muted: #4a473f;\\n    --shadow-sm: 0 2px 12px rgba(30, 58, 138, 0.08);\\n    --shadow-md: 0 8px 32px rgba(30, 58, 138, 0.12);\\n    --shadow-lg: 0 16px 48px rgba(30, 58, 138, 0.16);\\n    --radius: 12px;\\n    --radius-lg: 20px;\\n    --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);\\n    --font-sans: system-ui, -apple-system, \'Segoe UI\', Roboto, \'Helvetica Neue\', sans-serif;\\n    --header-height: 70px;\\n}\\n\\n\\/* ===== Reset & Base ===== *\\/\\n*,\\n*::before,\\n*::after {\\n    margin: 0;\\n    padding: 0;\\n    box-sizing: border-box;\\n}\\n\\nhtml {\\n    scroll-behavior: smooth;\\n    -webkit-font-smoothing: antialiased;\\n    -moz-osx-font-smoothing: grayscale;\\n}\\n\\nbody {\\n    font-family: var(--font-sans);\\n    background-color: var(--white);\\n    color: var(--text-dark);\\n    line-height: 1.7;\\n    overflow-x: hidden;\\n}\\n\\n\\/* ===== Skip Link ===== *\\/\\n.skip-link {\\n    position: absolute;\\n    top: -100%;\\n    left: 1rem;\\n    padding: 0.75rem 1.5rem;\\n    background: var(--deep-blue);\\n    color: var(--white);\\n    border-radius: 0 0 var(--radius) var(--radius);\\n    z-index: 10000;\\n    font-weight: 600;\\n    text-decoration: none;\\n    transition: top 0.25s ease;\\n}\\n.skip-link:focus {\\n    top: 0;\\n}\\n\\n\\/* ===== Container ===== *\\/\\n.container {\\n    max-width: 1200px;\\n    margin: 0 auto;\\n    padding: 0 1.25rem;\\n}\\n.container-narrow {\\n    max-width: 900px;\\n    margin: 0 auto;\\n    padding: 0 1.25rem;\\n}\\n\\n\\/* ===== Buttons ===== *\\/\\n.btn {\\n    display: inline-block;\\n    padding: 0.85rem 2.2rem;\\n    border: none;\\n    border-radius: 50px;\\n    font-size: 1rem;\\n    font-weight: 600;\\n    text-decoration: none;\\n    text-align: center;\\n    cursor: pointer;\\n    transition: var(--transition);\\n    font-family: inherit;\\n    line-height: 1.4;\\n}\\n\\n.btn-primary {\\n    background: var(--saffron);\\n    color: var(--white);\\n    box-shadow: 0 4px 16px rgba(255, 153, 51, 0.35);\\n}\\n.btn-primary:hover,\\n.btn-primary:focus {\\n    background: var(--saffron-dark);\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 28px rgba(255, 153, 51, 0.45);\\n}\\n.btn-primary:focus-visible {\\n    outline: 3px solid var(--deep-blue);\\n    outline-offset: 2px;\\n}\\n\\n.btn-outline {\\n    background: transparent;\\n    color: var(--deep-blue);\\n    border: 2px solid var(--deep-blue);\\n}\\n.btn-outline:hover,\\n.btn-outline:focus {\\n    background: var(--deep-blue);\\n    color: var(--white);\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 28px rgba(30, 58, 138, 0.25);\\n}\\n.btn-outline:focus-visible {\\n    outline: 3px solid var(--saffron);\\n    outline-offset: 2px;\\n}\\n\\n\\/* ===== Header \\/ Nav ===== *\\/\\n.site-header {\\n    background: var(--white);\\n    border-bottom: 2px solid var(--gray-light);\\n    padding: 0.9rem 0;\\n    position: sticky;\\n    top: 0;\\n    z-index: 1000;\\n    backdrop-filter: blur(8px);\\n    background: rgba(255, 255, 255, 0.92);\\n    min-height: var(--header-height);\\n    display: flex;\\n    align-items: center;\\n}\\n\\n.header-inner {\\n    display: flex;\\n    align-items: center;\\n    justify-content: space-between;\\n    flex-wrap: wrap;\\n    gap: 0.75rem 1.5rem;\\n    width: 100%;\\n}\\n\\n.logo {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5rem;\\n    text-decoration: none;\\n    color: var(--deep-blue);\\n    flex-shrink: 0;\\n}\\n.logo-icon {\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    width: 44px;\\n    height: 44px;\\n    background: var(--saffron);\\n    border-radius: 50%;\\n    color: var(--white);\\n    font-size: 1.5rem;\\n    font-weight: 700;\\n    flex-shrink: 0;\\n}\\n.logo-text {\\n    font-size: 1.3rem;\\n    font-weight: 700;\\n    letter-spacing: -0.02em;\\n}\\n.logo-text span {\\n    color: var(--saffron);\\n}\\n.logo-tagline {\\n    display: block;\\n    font-size: 0.7rem;\\n    font-weight: 400;\\n    color: var(--gray-mid);\\n    letter-spacing: 0.06em;\\n    text-transform: uppercase;\\n}\\n\\n.nav-links {\\n    display: flex;\\n    align-items: center;\\n    gap: 1.75rem;\\n    list-style: none;\\n}\\n.nav-links a {\\n    text-decoration: none;\\n    color: var(--text-dark);\\n    font-weight: 500;\\n    font-size: 0.95rem;\\n    transition: var(--transition);\\n    position: relative;\\n}\\n.nav-links a::after {\\n    content: \'\';\\n    position: absolute;\\n    bottom: -4px;\\n    left: 0;\\n    width: 0;\\n    height: 2px;\\n    background: var(--saffron);\\n    transition: var(--transition);\\n}\\n.nav-links a:hover::after,\\n.nav-links a:focus::after {\\n    width: 100%;\\n}\\n.nav-links a:focus-visible {\\n    outline: 2px solid var(--saffron);\\n    outline-offset: 4px;\\n    border-radius: 4px;\\n}\\n.nav-links .active {\\n    color: var(--saffron-dark);\\n    font-weight: 600;\\n}\\n.nav-links .active::after {\\n    width: 100%;\\n}\\n\\n.nav-toggle {\\n    display: none;\\n    flex-direction: column;\\n    gap: 5px;\\n    background: none;\\n    border: none;\\n    cursor: pointer;\\n    padding: 6px 4px;\\n    border-radius: 6px;\\n}\\n.nav-toggle span {\\n    display: block;\\n    width: 28px;\\n    height: 3px;\\n    background: var(--deep-blue);\\n    border-radius: 4px;\\n    transition: var(--transition);\\n    transform-origin: center;\\n}\\n.nav-toggle[aria-expanded=\\\"true\\\"] span:nth-child(1) {\\n    transform: rotate(45deg) translate(5px, 6px);\\n}\\n.nav-toggle[aria-expanded=\\\"true\\\"] span:nth-child(2) {\\n    opacity: 0;\\n}\\n.nav-toggle[aria-expanded=\\\"true\\\"] span:nth-child(3) {\\n    transform: rotate(-45deg) translate(5px, -6px);\\n}\\n.nav-toggle:focus-visible {\\n    outline: 2px solid var(--saffron);\\n    outline-offset: 2px;\\n}\\n\\n\\/* ===== Hero ===== *\\/\\n.hero {\\n    background: linear-gradient(145deg, var(--deep-blue) 0%, #0f2a5c 100%);\\n    color: var(--white);\\n    padding: 4rem 0 3.5rem;\\n    position: relative;\\n    overflow: hidden;\\n}\\n.hero::before {\\n    content: \'\\u0950\';\\n    position: absolute;\\n    right: -2rem;\\n    top: -2rem;\\n    font-size: 22rem;\\n    opacity: 0.035;\\n    pointer-events: none;\\n    line-height: 1;\\n    font-weight: 700;\\n    color: var(--white);\\n}\\n.hero::after {\\n    content: \'\';\\n    position: absolute;\\n    bottom: 0;\\n    left: 0;\\n    right: 0;\\n    height: 6px;\\n    background: var(--saffron);\\n}\\n.hero-content {\\n    position: relative;\\n    z-index: 2;\\n    max-width: 780px;\\n}\\n.hero-badge {\\n    display: inline-block;\\n    background: rgba(255, 153, 51, 0.20);\\n    color: var(--saffron-light);\\n    padding: 0.3rem 1.2rem;\\n    border-radius: 50px;\\n    font-size: 0.8rem;\\n    font-weight: 600;\\n    letter-spacing: 0.06em;\\n    text-transform: uppercase;\\n    margin-bottom: 1.2rem;\\n    border: 1px solid rgba(255, 153, 51, 0.25);\\n}\\n.hero h1 {\\n    font-size: clamp(2.4rem, 7vw, 3.8rem);\\n    font-weight: 800;\\n    line-height: 1.1;\\n    letter-spacing: -0.02em;\\n    margin-bottom: 0.5rem;\\n}\\n.hero h1 .highlight {\\n    color: var(--saffron);\\n}\\n.hero p {\\n    font-size: 1.1rem;\\n    color: rgba(255, 255, 255, 0.85);\\n    max-width: 620px;\\n    margin-bottom: 1.5rem;\\n    line-height: 1.8;\\n}\\n\\n.hero-image-wrapper {\\n    margin-bottom: 1.5rem;\\n    max-width: 180px;\\n}\\n.hero-image-placeholder {\\n    width: 100%;\\n    aspect-ratio: 1\\/1;\\n    background: rgba(255, 255, 255, 0.08);\\n    border-radius: var(--radius-lg);\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    font-size: 4rem;\\n    border: 2px dashed rgba(255, 255, 255, 0.15);\\n    transition: var(--transition);\\n}\\n.hero-image-placeholder:hover {\\n    border-color: var(--saffron);\\n    background: rgba(255, 153, 51, 0.08);\\n}\\n\\n.hero-meta {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 1.5rem 2.5rem;\\n    background: rgba(255, 255, 255, 0.08);\\n    padding: 1rem 1.5rem;\\n    border-radius: var(--radius);\\n    border: 1px solid rgba(255, 255, 255, 0.10);\\n    backdrop-filter: blur(4px);\\n}\\n.hero-meta-item {\\n    display: flex;\\n    align-items: center;\\n    gap: 0.5rem;\\n    font-size: 0.9rem;\\n    color: rgba(255, 255, 255, 0.8);\\n}\\n.hero-meta-item strong {\\n    color: var(--white);\\n    font-weight: 600;\\n}\\n.hero-meta-item .placeholder-badge {\\n    background: rgba(255, 153, 51, 0.25);\\n    color: var(--saffron-light);\\n    padding: 0.15rem 0.7rem;\\n    border-radius: 50px;\\n    font-size: 0.75rem;\\n    font-weight: 500;\\n    letter-spacing: 0.03em;\\n    border: 1px dashed rgba(255, 153, 51, 0.4);\\n}\\n\\n\\/* ===== Table of Contents ===== *\\/\\n.toc-section {\\n    background: var(--off-white);\\n    padding: 2rem 0;\\n    border-bottom: 1px solid var(--gray-light);\\n}\\n.toc-wrapper {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 0.4rem 0.8rem;\\n    align-items: center;\\n    justify-content: center;\\n}\\n.toc-label {\\n    font-weight: 700;\\n    color: var(--deep-blue);\\n    font-size: 0.9rem;\\n    margin-right: 0.25rem;\\n}\\n.toc-link {\\n    color: var(--text-muted);\\n    text-decoration: none;\\n    font-size: 0.8rem;\\n    font-weight: 500;\\n    padding: 0.2rem 0.6rem;\\n    border-radius: 6px;\\n    transition: var(--transition);\\n    border: 1px solid transparent;\\n}\\n.toc-link:hover,\\n.toc-link:focus {\\n    color: var(--deep-blue);\\n    background: var(--white);\\n    border-color: var(--saffron);\\n    box-shadow: var(--shadow-sm);\\n}\\n.toc-link:focus-visible {\\n    outline: 2px solid var(--saffron);\\n    outline-offset: 2px;\\n}\\n\\n\\/* ===== Section Shared ===== *\\/\\nsection {\\n    padding: 3.5rem 0;\\n}\\n.section-title {\\n    font-size: clamp(1.8rem, 4vw, 2.4rem);\\n    font-weight: 700;\\n    color: var(--deep-blue);\\n    margin-bottom: 0.75rem;\\n    letter-spacing: -0.02em;\\n    line-height: 1.2;\\n}\\n.section-title .highlight {\\n    color: var(--saffron);\\n}\\n.section-subtitle {\\n    font-size: 1.05rem;\\n    color: var(--text-muted);\\n    max-width: 700px;\\n    margin-bottom: 1.5rem;\\n    line-height: 1.8;\\n}\\n.text-center {\\n    text-align: center;\\n}\\n\\n.bg-light {\\n    background: var(--light-bg);\\n}\\n.bg-offwhite {\\n    background: var(--off-white);\\n}\\n.bg-white {\\n    background: var(--white);\\n}\\n\\n\\/* ===== Terms Content ===== *\\/\\n.terms-content {\\n    max-width: 860px;\\n    margin: 0 auto;\\n}\\n.terms-block {\\n    margin-bottom: 2.5rem;\\n    padding-bottom: 2.5rem;\\n    border-bottom: 1px solid var(--gray-light);\\n}\\n.terms-block:last-of-type {\\n    border-bottom: none;\\n    margin-bottom: 0;\\n    padding-bottom: 0;\\n}\\n.terms-block h2 {\\n    font-size: 1.6rem;\\n    font-weight: 700;\\n    color: var(--deep-blue);\\n    margin-bottom: 0.75rem;\\n    display: flex;\\n    align-items: center;\\n    gap: 0.6rem;\\n}\\n.terms-block h2 .section-number {\\n    color: var(--saffron);\\n    font-size: 1.2rem;\\n    font-weight: 700;\\n    opacity: 0.7;\\n}\\n.terms-block h3 {\\n    font-size: 1.15rem;\\n    font-weight: 600;\\n    color: var(--deep-blue);\\n    margin-top: 1.2rem;\\n    margin-bottom: 0.4rem;\\n}\\n.terms-block p {\\n    font-size: 1rem;\\n    color: var(--text-muted);\\n    line-height: 1.8;\\n    margin-bottom: 0.75rem;\\n}\\n.terms-block p:last-child {\\n    margin-bottom: 0;\\n}\\n.terms-block ul,\\n.terms-block ol {\\n    padding-left: 1.5rem;\\n    margin: 0.5rem 0 1rem;\\n    color: var(--text-muted);\\n    line-height: 1.8;\\n}\\n.terms-block ul li,\\n.terms-block ol li {\\n    margin-bottom: 0.3rem;\\n}\\n.terms-block ul li:last-child,\\n.terms-block ol li:last-child {\\n    margin-bottom: 0;\\n}\\n\\n\\/* ===== Placeholder Boxes ===== *\\/\\n.placeholder-box {\\n    background: var(--off-white);\\n    border: 2px dashed var(--gray-mid);\\n    border-radius: var(--radius);\\n    padding: 1.5rem 1.75rem;\\n    margin: 1rem 0 0.5rem;\\n    transition: var(--transition);\\n}\\n.placeholder-box:hover {\\n    border-color: var(--saffron);\\n    background: #fcf8f0;\\n}\\n.placeholder-box .placeholder-label {\\n    display: inline-block;\\n    background: var(--deep-blue);\\n    color: var(--white);\\n    font-size: 0.7rem;\\n    font-weight: 600;\\n    text-transform: uppercase;\\n    letter-spacing: 0.06em;\\n    padding: 0.2rem 0.8rem;\\n    border-radius: 50px;\\n    margin-bottom: 0.6rem;\\n}\\n.placeholder-box .placeholder-content {\\n    color: var(--gray-mid);\\n    font-style: italic;\\n    font-size: 0.95rem;\\n    padding: 0.25rem 0;\\n}\\n.placeholder-box .placeholder-content .icon {\\n    margin-right: 0.4rem;\\n    opacity: 0.6;\\n}\\n.placeholder-box .placeholder-note {\\n    font-size: 0.8rem;\\n    color: var(--gray-mid);\\n    margin-top: 0.4rem;\\n    border-top: 1px solid var(--gray-light);\\n    padding-top: 0.4rem;\\n    opacity: 0.7;\\n}\\n\\n\\/* ===== Contact Box ===== *\\/\\n.contact-box {\\n    background: var(--deep-blue);\\n    color: var(--white);\\n    padding: 2.5rem 2.5rem;\\n    border-radius: var(--radius-lg);\\n    box-shadow: var(--shadow-lg);\\n    max-width: 780px;\\n    margin: 0 auto;\\n    text-align: center;\\n}\\n.contact-box h2 {\\n    font-size: 1.8rem;\\n    font-weight: 700;\\n    margin-bottom: 0.5rem;\\n    color: var(--white);\\n}\\n.contact-box p {\\n    color: rgba(255, 255, 255, 0.8);\\n    font-size: 1rem;\\n    margin-bottom: 1.5rem;\\n}\\n.contact-box .email-link {\\n    display: inline-flex;\\n    align-items: center;\\n    gap: 0.6rem;\\n    background: var(--saffron);\\n    color: var(--white);\\n    padding: 0.85rem 2.2rem;\\n    border-radius: 50px;\\n    text-decoration: none;\\n    font-weight: 600;\\n    font-size: 1.05rem;\\n    transition: var(--transition);\\n    box-shadow: 0 4px 16px rgba(255, 153, 51, 0.3);\\n}\\n.contact-box .email-link:hover,\\n.contact-box .email-link:focus {\\n    background: var(--saffron-dark);\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 28px rgba(255, 153, 51, 0.45);\\n}\\n.contact-box .email-link:focus-visible {\\n    outline: 3px solid var(--white);\\n    outline-offset: 2px;\\n}\\n\\n.contact-placeholders {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 1rem;\\n    justify-content: center;\\n    margin-top: 1.5rem;\\n}\\n.contact-placeholders .placeholder-box {\\n    background: rgba(255, 255, 255, 0.06);\\n    border-color: rgba(255, 255, 255, 0.15);\\n    margin: 0;\\n    flex: 1;\\n    min-width: 180px;\\n    text-align: left;\\n}\\n.contact-placeholders .placeholder-box .placeholder-label {\\n    background: rgba(255, 255, 255, 0.12);\\n    color: var(--saffron-light);\\n}\\n.contact-placeholders .placeholder-box .placeholder-content {\\n    color: rgba(255, 255, 255, 0.6);\\n}\\n.contact-placeholders .placeholder-box .placeholder-note {\\n    color: rgba(255, 255, 255, 0.3);\\n    border-color: rgba(255, 255, 255, 0.08);\\n}\\n\\n\\/* ===== Footer ===== *\\/\\n.site-footer {\\n    background: var(--deep-blue-dark);\\n    color: rgba(255, 255, 255, 0.8);\\n    padding: 2.5rem 0 2rem;\\n    border-top: 4px solid var(--saffron);\\n}\\n.footer-inner {\\n    display: flex;\\n    flex-wrap: wrap;\\n    justify-content: space-between;\\n    align-items: center;\\n    gap: 1rem 2rem;\\n}\\n.footer-brand .footer-logo {\\n    font-size: 1.3rem;\\n    font-weight: 700;\\n    color: var(--white);\\n}\\n.footer-brand .footer-logo span {\\n    color: var(--saffron);\\n}\\n.footer-brand .footer-tagline {\\n    font-size: 0.85rem;\\n    color: rgba(255, 255, 255, 0.55);\\n    font-style: italic;\\n    letter-spacing: 0.04em;\\n}\\n.footer-links {\\n    display: flex;\\n    flex-wrap: wrap;\\n    gap: 1.25rem 2rem;\\n    list-style: none;\\n}\\n.footer-links a {\\n    color: rgba(255, 255, 255, 0.65);\\n    text-decoration: none;\\n    font-size: 0.9rem;\\n    transition: var(--transition);\\n}\\n.footer-links a:hover,\\n.footer-links a:focus {\\n    color: var(--saffron);\\n}\\n.footer-links a:focus-visible {\\n    outline: 2px solid var(--saffron);\\n    outline-offset: 4px;\\n    border-radius: 4px;\\n}\\n.footer-copy {\\n    font-size: 0.9rem;\\n    color: rgba(255, 255, 255, 0.5);\\n    text-align: right;\\n}\\n.footer-copy .year {\\n    font-weight: 600;\\n}\\n\\n\\/* ===== Animations ===== *\\/\\n@keyframes fadeInUp {\\n    from {\\n        opacity: 0;\\n        transform: translateY(30px);\\n    }\\n    to {\\n        opacity: 1;\\n        transform: translateY(0);\\n    }\\n}\\n.animate-on-view {\\n    opacity: 0;\\n    transform: translateY(30px);\\n    transition: opacity 0.7s ease, transform 0.7s ease;\\n}\\n.animate-on-view.visible {\\n    opacity: 1;\\n    transform: translateY(0);\\n}\\n\\n\\/* ============================================================\\n   RESPONSIVE BREAKPOINTS\\n   ============================================================ *\\/\\n\\n\\/* ===== 320px+ (Base \\/ Mobile First) ===== *\\/\\n@media (max-width: 479px) {\\n    .container {\\n        padding: 0 0.9rem;\\n    }\\n    .container-narrow {\\n        padding: 0 0.9rem;\\n    }\\n\\n    .hero {\\n        padding: 2.5rem 0 2rem;\\n    }\\n    .hero h1 {\\n        font-size: 1.8rem;\\n    }\\n    .hero p {\\n        font-size: 0.95rem;\\n    }\\n    .hero-image-wrapper {\\n        max-width: 120px;\\n    }\\n    .hero-image-placeholder {\\n        font-size: 2.8rem;\\n    }\\n    .hero-meta {\\n        flex-direction: column;\\n        gap: 0.5rem;\\n        padding: 0.75rem 1rem;\\n    }\\n    .hero-meta-item {\\n        font-size: 0.8rem;\\n    }\\n\\n    .toc-wrapper {\\n        gap: 0.25rem 0.5rem;\\n    }\\n    .toc-link {\\n        font-size: 0.7rem;\\n        padding: 0.15rem 0.4rem;\\n    }\\n    .toc-label {\\n        font-size: 0.75rem;\\n        width: 100%;\\n        text-align: center;\\n    }\\n\\n    .terms-block h2 {\\n        font-size: 1.2rem;\\n    }\\n    .terms-block h2 .section-number {\\n        font-size: 1rem;\\n    }\\n    .terms-block p,\\n    .terms-block ul,\\n    .terms-block ol {\\n        font-size: 0.9rem;\\n    }\\n    .terms-block ul,\\n    .terms-block ol {\\n        padding-left: 1.2rem;\\n    }\\n\\n    .placeholder-box {\\n        padding: 1rem 1.25rem;\\n    }\\n    .placeholder-box .placeholder-content {\\n        font-size: 0.85rem;\\n    }\\n\\n    .contact-box {\\n        padding: 1.5rem 1rem;\\n    }\\n    .contact-box h2 {\\n        font-size: 1.3rem;\\n    }\\n    .contact-box .email-link {\\n        font-size: 0.9rem;\\n        padding: 0.7rem 1.5rem;\\n        width: 100%;\\n        justify-content: center;\\n    }\\n    .contact-placeholders {\\n        flex-direction: column;\\n    }\\n    .contact-placeholders .placeholder-box {\\n        min-width: unset;\\n    }\\n\\n    .footer-inner {\\n        flex-direction: column;\\n        text-align: center;\\n    }\\n    .footer-copy {\\n        text-align: center;\\n    }\\n    .footer-links {\\n        justify-content: center;\\n    }\\n\\n    .logo-text {\\n        font-size: 1rem;\\n    }\\n    .logo-icon {\\n        width: 36px;\\n        height: 36px;\\n        font-size: 1.1rem;\\n    }\\n    .logo-tagline {\\n        font-size: 0.6rem;\\n    }\\n\\n    section {\\n        padding: 2.5rem 0;\\n    }\\n    .toc-section {\\n        padding: 1.25rem 0;\\n    }\\n}\\n\\n\\/* ===== 480px+ ===== *\\/\\n@media (min-width: 480px) and (max-width: 767px) {\\n    .container {\\n        padding: 0 1.1rem;\\n    }\\n    .container-narrow {\\n        padding: 0 1.1rem;\\n    }\\n\\n    .hero {\\n        padding: 3rem 0 2.5rem;\\n    }\\n    .hero h1 {\\n        font-size: 2.2rem;\\n    }\\n    .hero-image-wrapper {\\n        max-width: 140px;\\n    }\\n    .hero-image-placeholder {\\n        font-size: 3.2rem;\\n    }\\n    .hero-meta {\\n        flex-direction: column;\\n        gap: 0.6rem;\\n    }\\n\\n    .terms-block h2 {\\n        font-size: 1.4rem;\\n    }\\n\\n    .contact-box {\\n        padding: 2rem 1.5rem;\\n    }\\n    .contact-box h2 {\\n        font-size: 1.5rem;\\n    }\\n    .contact-placeholders {\\n        flex-direction: column;\\n    }\\n    .contact-placeholders .placeholder-box {\\n        min-width: unset;\\n    }\\n\\n    .footer-inner {\\n        flex-direction: column;\\n        text-align: center;\\n    }\\n    .footer-copy {\\n        text-align: center;\\n    }\\n    .footer-links {\\n        justify-content: center;\\n    }\\n}\\n\\n\\/* ===== 768px+ (Tablet) ===== *\\/\\n@media (min-width: 768px) and (max-width: 1023px) {\\n    .container {\\n        padding: 0 1.5rem;\\n    }\\n    .container-narrow {\\n        padding: 0 1.5rem;\\n    }\\n\\n    .hero {\\n        padding: 3.5rem 0 3rem;\\n    }\\n    .hero h1 {\\n        font-size: 2.8rem;\\n    }\\n    .hero-image-wrapper {\\n        max-width: 160px;\\n    }\\n    .hero-image-placeholder {\\n        font-size: 3.6rem;\\n    }\\n    .hero-meta {\\n        flex-wrap: wrap;\\n        gap: 0.8rem 2rem;\\n    }\\n\\n    .toc-wrapper {\\n        gap: 0.4rem 0.8rem;\\n    }\\n    .toc-link {\\n        font-size: 0.8rem;\\n    }\\n\\n    .terms-block h2 {\\n        font-size: 1.5rem;\\n    }\\n\\n    .contact-box {\\n        padding: 2.5rem 2rem;\\n    }\\n    .contact-placeholders {\\n        flex-wrap: wrap;\\n    }\\n    .contact-placeholders .placeholder-box {\\n        min-width: 200px;\\n        flex: 1 1 45%;\\n    }\\n\\n    .footer-inner {\\n        flex-wrap: wrap;\\n        gap: 1.5rem 2rem;\\n    }\\n}\\n\\n\\/* ===== 1024px+ (Laptop \\/ Desktop) ===== *\\/\\n@media (min-width: 1024px) and (max-width: 1439px) {\\n    .container {\\n        padding: 0 2rem;\\n    }\\n    .container-narrow {\\n        padding: 0 2rem;\\n    }\\n\\n    .hero {\\n        padding: 4.5rem 0 3.5rem;\\n    }\\n    .hero h1 {\\n        font-size: 3.4rem;\\n    }\\n    .hero-image-wrapper {\\n        max-width: 180px;\\n    }\\n    .hero-image-placeholder {\\n        font-size: 4rem;\\n    }\\n    .hero-meta {\\n        gap: 1.5rem 2.5rem;\\n    }\\n\\n    .toc-link {\\n        font-size: 0.85rem;\\n        padding: 0.25rem 0.7rem;\\n    }\\n\\n    .terms-block h2 {\\n        font-size: 1.6rem;\\n    }\\n\\n    .contact-box {\\n        padding: 3rem 3rem;\\n    }\\n    .contact-box h2 {\\n        font-size: 1.8rem;\\n    }\\n    .contact-placeholders .placeholder-box {\\n        min-width: 220px;\\n        flex: 1 1 40%;\\n    }\\n}\\n\\n\\/* ===== 1440px+ (Large Displays) ===== *\\/\\n@media (min-width: 1440px) {\\n    .container {\\n        max-width: 1280px;\\n        padding: 0 2.5rem;\\n    }\\n    .container-narrow {\\n        max-width: 1000px;\\n        padding: 0 2.5rem;\\n    }\\n\\n    .hero {\\n        padding: 5rem 0 4rem;\\n    }\\n    .hero h1 {\\n        font-size: 4.2rem;\\n    }\\n    .hero p {\\n        font-size: 1.2rem;\\n    }\\n    .hero-image-wrapper {\\n        max-width: 200px;\\n    }\\n    .hero-image-placeholder {\\n        font-size: 4.5rem;\\n    }\\n    .hero-meta {\\n        gap: 2rem 3rem;\\n        padding: 1.25rem 2rem;\\n    }\\n    .hero-meta-item {\\n        font-size: 1rem;\\n    }\\n\\n    .toc-wrapper {\\n        gap: 0.5rem 1.2rem;\\n    }\\n    .toc-link {\\n        font-size: 0.9rem;\\n        padding: 0.3rem 0.9rem;\\n    }\\n\\n    section {\\n        padding: 4.5rem 0;\\n    }\\n    .terms-block h2 {\\n        font-size: 1.8rem;\\n    }\\n    .terms-block p,\\n    .terms-block ul,\\n    .terms-block ol {\\n        font-size: 1.05rem;\\n    }\\n\\n    .contact-box {\\n        padding: 3.5rem 3.5rem;\\n        max-width: 820px;\\n    }\\n    .contact-box h2 {\\n        font-size: 2rem;\\n    }\\n    .contact-box p {\\n        font-size: 1.05rem;\\n    }\\n    .contact-placeholders .placeholder-box {\\n        min-width: 240px;\\n    }\\n\\n    .footer-inner {\\n        gap: 1.5rem 3rem;\\n    }\\n    .footer-brand .footer-logo {\\n        font-size: 1.5rem;\\n    }\\n    .footer-links a {\\n        font-size: 1rem;\\n    }\\n    .footer-copy {\\n        font-size: 1rem;\\n    }\\n}\\n\\n\\/* ============================================================\\n   NAVIGATION RESPONSIVE (mobile toggle)\\n   ============================================================ *\\/\\n@media (max-width: 767px) {\\n    .nav-toggle {\\n        display: flex;\\n    }\\n    .nav-links {\\n        display: none;\\n        flex-direction: column;\\n        width: 100%;\\n        padding: 1rem 0 0.5rem;\\n        gap: 0.75rem;\\n        border-top: 1px solid var(--gray-light);\\n        margin-top: 0.5rem;\\n    }\\n    .nav-links.open {\\n        display: flex;\\n    }\\n    .header-inner {\\n        flex-wrap: wrap;\\n    }\\n    .site-header {\\n        padding: 0.6rem 0;\\n    }\\n}\\n\\n\\/* ============================================================\\n   UTILITY \\u2014 No horizontal scroll\\n   ============================================================ *\\/\\nimg,\\nsvg,\\nvideo,\\niframe {\\n    max-width: 100%;\\n    height: auto;\\n    display: block;\\n}\\n\\n\\/* ============================================================\\n   ACCESSIBILITY \\u2014 Focus visible\\n   ============================================================ *\\/\\n:focus-visible {\\n    outline: 2px solid var(--saffron);\\n    outline-offset: 2px;\\n}\\n\\n\\/* ============================================================\\n   PRINT STYLES (basic)\\n   ============================================================ *\\/\\n@media print {\\n    .site-header,\\n    .toc-section,\\n    .nav-toggle,\\n    .site-footer {\\n        display: none !important;\\n    }\\n    body {\\n        background: white;\\n        color: black;\\n        font-size: 12pt;\\n        line-height: 1.5;\\n    }\\n    .hero {\\n        background: white !important;\\n        color: black !important;\\n        padding: 1rem 0 !important;\\n    }\\n    .hero h1 .highlight {\\n        color: var(--saffron) !important;\\n    }\\n    .hero p {\\n        color: black !important;\\n    }\\n    .hero-meta {\\n        background: #f5f5f5 !important;\\n        border: 1px solid #ddd !important;\\n    }\\n    .hero-meta-item {\\n        color: #333 !important;\\n    }\\n    .hero-meta-item strong {\\n        color: #000 !important;\\n    }\\n    .placeholder-badge {\\n        border: 1px solid #999 !important;\\n        background: #eee !important;\\n        color: #333 !important;\\n    }\\n    .placeholder-box {\\n        border: 1px solid #999 !important;\\n        background: #f9f9f9 !important;\\n    }\\n    .terms-block {\\n        border-bottom: 1px solid #ddd !important;\\n    }\\n    .contact-box {\\n        background: #f5f5f5 !important;\\n        color: #000 !important;\\n        border: 1px solid #ddd !important;\\n    }\\n    .contact-box h2 {\\n        color: #000 !important;\\n    }\\n    .contact-box p {\\n        color: #333 !important;\\n    }\\n    .contact-box .email-link {\\n        background: var(--saffron) !important;\\n        color: #000 !important;\\n        box-shadow: none !important;\\n    }\\n    .hero-image-placeholder {\\n        border: 1px solid #ccc !important;\\n        background: #f0f0f0 !important;\\n    }\\n}\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false,\"styles\":{\"e-8931e4a\":{\"id\":\"e-8931e4a\",\"label\":\"local\",\"type\":\"class\",\"variants\":[{\"meta\":{\"breakpoint\":\"desktop\",\"state\":null},\"props\":{\"flex-direction\":{\"$$type\":\"string\",\"value\":\"column\"}},\"custom_css\":null}]}},\"interactions\":[],\"editor_settings\":[],\"version\":\"0.0\"}]'),
