INSERT INTO `wp_wpcode_revisions` VALUES
(1,110,'{\"id\":110,\"title\":\"Display a message after the 1st paragraph of posts\",\"code\":\"Thank you for reading this post, don\'t forget to subscribe!\",\"code_type\":\"text\",\"location\":\"after_paragraph\",\"auto_insert\":1,\"insert_number\":1,\"use_rules\":false,\"rules\":[],\"priority\":10,\"location_extra\":\"\",\"shortcode_attributes\":[],\"compiled_code\":\"\",\"modified\":0,\"note\":\"\",\"tags\":[\"message\",\"sample\"],\"custom_shortcode\":\"\",\"device_type\":\"any\",\"schedule\":{\"start\":\"\",\"end\":\"\"}}',1,'2026-07-06 17:01:24',''),
(2,111,'{\"id\":111,\"title\":\"Completely Disable Comments\",\"code\":\"add_action(\'admin_init\', function () {\\r\\n    \\/\\/ Redirect any user trying to access comments page\\r\\n    global $pagenow;\\r\\n    \\r\\n    if ($pagenow === \'edit-comments.php\') {\\r\\n        wp_safe_redirect(admin_url());\\r\\n        exit;\\r\\n    }\\r\\n\\r\\n    \\/\\/ Remove comments metabox from dashboard\\r\\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\\r\\n\\r\\n    \\/\\/ Disable support for comments and trackbacks in post types\\r\\n    foreach (get_post_types() as $post_type) {\\r\\n        if (post_type_supports($post_type, \'comments\')) {\\r\\n            remove_post_type_support($post_type, \'comments\');\\r\\n            remove_post_type_support($post_type, \'trackbacks\');\\r\\n        }\\r\\n    }\\r\\n});\\r\\n\\r\\n\\/\\/ Close comments on the front-end\\r\\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\\r\\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\\r\\n\\r\\n\\/\\/ Hide existing comments\\r\\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\\r\\n\\r\\n\\/\\/ Remove comments page in menu\\r\\nadd_action(\'admin_menu\', function () {\\r\\n    remove_menu_page(\'edit-comments.php\');\\r\\n});\\r\\n\\r\\n\\/\\/ Remove comments links from admin bar\\r\\nadd_action(\'init\', function () {\\r\\n    if (is_admin_bar_showing()) {\\r\\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\\r\\n    }\\r\\n});\",\"code_type\":\"php\",\"location\":\"everywhere\",\"auto_insert\":1,\"insert_number\":1,\"use_rules\":false,\"rules\":[],\"priority\":10,\"location_extra\":\"\",\"shortcode_attributes\":[],\"compiled_code\":\"\",\"modified\":0,\"note\":\"\",\"tags\":[\"comments\",\"disable\",\"sample\"],\"custom_shortcode\":\"\",\"device_type\":\"any\",\"schedule\":{\"start\":\"\",\"end\":\"\"}}',1,'2026-07-06 17:01:24',''),
(3,134,'{\"_wpcode_header_scripts\":{\"disable_global\":false,\"any\":\"\",\"desktop\":\"\",\"mobile\":\"\"},\"_wpcode_footer_scripts\":{\"disable_global\":false,\"any\":\"\",\"desktop\":\"\",\"mobile\":\"\"},\"_wpcode_body_scripts\":{\"disable_global\":false,\"any\":\"\",\"desktop\":\"\",\"mobile\":\"\"},\"_wpcode_page_snippets\":[]}',1,'2026-07-09 02:42:12','');
